const rows = $input.all();

// ดึงทุกแถวจาก sheet ไม่ใช่แค่แถวแรก
const sheetRows = [];
try {
  const all = $('Get row(s) in sheet').all();
  if (all && all.length > 0) {
    all.forEach(item => {
      if (item.json && !item.json.error) sheetRows.push(item.json);
    });
  }
} catch (e) {}

// รวม productFields จากทุกแถว
const productFields = [];
sheetRows.forEach(sheetData => {
  Object.entries(sheetData)
    .filter(([key]) => key.startsWith('ชื่อสินค้า#'))
    .forEach(([_, val]) => {
      if (val) productFields.push(val);
    });
});

function findMatch(keyword) {
  if (!keyword || productFields.length === 0) return null;
  const found = productFields.find(val =>
    val.toString().includes(keyword.toString().trim())
  );
  return found || null;
}

return rows.map(item => {
  const row = { ...item.json };
  if (row.row === 1 && row.T1_A != null) {
    row.T1_A = findMatch(row.T1_A) ?? row.T1_A;
  }
  return { json: row };
});

const mergedRows = {};
const tables = $('cvt-text-to-json-1').all().map(item => item.json);
tables.forEach((table, tableIndex) => {
  if (table.result && Array.isArray(table.result)) {
    table.result.forEach((rowItem) => {
      const rowData = rowItem.json;
      if (rowData && rowData.row) {
        const rowNum = rowData.row;
        if (!mergedRows[rowNum]) { mergedRows[rowNum] = { row: rowNum }; }
        if (rowData.response) {
          for (const [key, value] of Object.entries(rowData.response)) {
            let cleanValue = value;
            if ((typeof cleanValue === 'string' && cleanValue.trim().toLowerCase() === 'null') || (typeof cleanValue === 'string' && cleanValue.trim().toLowerCase() === '-') || (typeof cleanValue === 'string' && cleanValue.trim().toLowerCase() === '0')) {
              cleanValue = null;
            }
            // if (rowNum===2 && key === "B") {
            //   cleanValue = $input.last().json.name;
            // }
            mergedRows[rowNum][`T${tableIndex + 1}_${key}`] = cleanValue;
          }
        }
      }
    });
  }
});
const finalResult = Object.values(mergedRows).sort((a, b) => a.row - b.row);
return finalResult.map(row => ({ json: row }));

const N = 9; // จำนวนคู่ ชื่อปัญหาคุณภาพ-/Qty-

return items.map(item => {
  const row = item.json;

  // 1) เก็บเฉพาะคู่ที่ Qty > 0 (เรียงตามลำดับเดิม)
  const validPairs = [];
  for (let i = 1; i <= N; i++) {
    const qty = row[`Qty-${i}`];
    if (qty !== null && qty !== undefined && qty !== 0) {
      validPairs.push({
        name: row[`ชื่อปัญหาคุณภาพ-${i}`],
        qty: qty,
      });
    }
  }

  // 2) เคลียร์ทุกคู่เป็น null ก่อน
  for (let i = 1; i <= N; i++) {
    row[`ชื่อปัญหาคุณภาพ-${i}`] = null;
    row[`Qty-${i}`] = null;
  }

  // 3) ขยับคู่ที่มีค่าขึ้นมาเรียงต่อกันจากคู่ที่ 1
  if (validPairs.length > 0) {
    validPairs.forEach((p, idx) => {
      row[`ชื่อปัญหาคุณภาพ-${idx + 1}`] = p.name;
      row[`Qty-${idx + 1}`] = p.qty;
    });
  } else {
    // 4) ถ้าไม่มีปัญหาเลย
    row['ชื่อปัญหาคุณภาพ-1'] = 'ไม่พบปัญหา';
    // Qty-1 และคู่ที่เหลือเป็น null อยู่แล้วจากขั้นตอนที่ 2
  }

  return { json: row };
});

// ===== เตรียมรายการแถวที่จะอัปเดตสูตร =====

// 1) row_number ของแถวสุดท้ายในชีต = แถวล่าสุดที่เพิ่ง insert เข้าไป
//    (รับมาจาก Get row(s) in sheet2 -> Limit1 ซึ่งเหลือ item สุดท้ายไว้ตัวเดียว)
const lastRow = $input.first().json.row_number;

// 2) จำนวนแถวที่ insert ไปในรอบนี้
//    = จำนวน item ที่ออกจาก node "Code in JavaScript5" (ตัวที่ป้อนเข้า Append)
const insertedCount = $('Code in JavaScript1').all().length;

// กันพลาด: ไม่มีอะไรให้อัปเดตก็จบเลย
if (!lastRow || insertedCount === 0) {
  return [];
}

// 3) ไล่จากแถวล่าสุด "ลบลงทีละ 1" จนครบจำนวนที่ insert ไปตอนแรก
const out = [];
for (let i = 0; i < insertedCount; i++) {
  const row = lastRow - i;

  out.push({
    json: {
      row_number: row, // ใช้เป็นคีย์ match แถวตอน update

      // ===== สูตรชีตที่อ้างอิงเลขแถวจริงของแถวนั้น ๆ =====
      // Count = รวม Qty-1..Qty-9 (คอลัมน์ K ถึง AA)
      'Cal-Wt.': `=VLOOKUP(C${row},Sheet4!A:AA,27,false)`,
      'Count': `=SUM(K${row}:AA${row})`,
      'Total Wt.': `=AQ${row}*AP${row}`,
      'Month': `=MONTH(A${row})`

      // อยากอัปเดตสูตรคอลัมน์อื่นเพิ่ม ใส่ต่อตรงนี้ แล้วไป map เพิ่มใน node Update เช่น
      // 'Total Wt.': `=AB${row}*AC${row}`,
      // 'Month': `=TEXT(DATEVALUE(A${row}),"mm-yyyy")`,
    },
  });
}

return out;

// ระบุชื่อ Node ที่ต้องการคำนวณ
const geminiNodes = [
  'ocr-agent-1',
  'ocr-agent-2',
  'ocr-agent-3',
];

// 1. ตารางราคา (USD ต่อ 1 ล้าน Tokens)
// เงื่อนไข: เฉพาะ Text Output และ Prompt <= 200,000 Tokens 
const pricing = {
  "gemini-3.5-flash": { input: 1.5, output: 8.3 },
  // ตระกูล Gemini 3.1 (รุ่นใหม่ล่าสุด)
  "gemini-3.1-pro": { input: 2.00, output: 12.00 },
  "gemini-3.1-flash": { input: 0.50, output: 3.00 },
  "gemini-3.1-flash-lite": { input: 0.25, output: 1.50 },

  // ตระกูล Gemini 2.5
  "gemini-2.5-pro": { input: 1.25, output: 10.00 },
  "gemini-2.5-flash": { input: 0.30, output: 2.50 },
  "gemini-2.5-flash-lite": { input: 0.10, output: 0.40 },

  // Default สำรองไว้กรณีหาชื่อรุ่นไม่เจอ (อิงเรทกลางๆ ของ 2.5 Flash)
  "default": { input: 0.30, output: 2.50 } 
};

let grandTotalUsd = 0;
let totalInputAll = 0;
let totalOutputAll = 0;

// Object สำหรับเก็บสรุปยอดแยกตามโมเดล
let summaryByModel = {};

// 2. วนลูปดึงข้อมูลจากแต่ละ Node
for (const nodeName of geminiNodes) {
  try {
    const nodeData = $node[nodeName].json;
    const meta = nodeData.usageMetadata;

    // ดึงชื่อรุ่นจาก API ถ้าไม่มีให้ใช้ "default"
    let rawModelVersion = nodeData.modelVersion || "default";
    let matchedModel = "default";
    let rate = pricing["default"];

    // ใช้การเช็กคำ (includes) เพื่อรองรับชื่อ API ที่มี suffix ต่อท้าย เช่น "gemini-2.5-pro-preview"
    for (const key in pricing) {
      if (rawModelVersion.includes(key)) {
        matchedModel = key;
        rate = pricing[key];
        break; // เจอชื่อที่ตรงกันแล้วหยุดหา
      }
    }

    if (meta) {
      const inputTokens = meta.promptTokenCount || 0;
      // รวม Candidates (คำตอบปกติ) และ Thoughts (การคิดวิเคราะห์) เข้าเป็น Output ก้อนเดียว
      const outputTokens = (meta.candidatesTokenCount || 0) + (meta.thoughtsTokenCount || 0);

      // 3. คำนวณราคา Node ปัจจุบัน
      const nodeCostUsd = (inputTokens * (rate.input / 1000000)) + (outputTokens * (rate.output / 1000000));

      grandTotalUsd += nodeCostUsd;
      totalInputAll += inputTokens;
      totalOutputAll += outputTokens;

      // บันทึกสถิติสะสมแยกตามรุ่นโมเดล
      if (!summaryByModel[matchedModel]) {
        summaryByModel[matchedModel] = {
          total_tokens: 0,
          cost_usd: 0
        };
      }
      summaryByModel[matchedModel].total_tokens += (inputTokens + outputTokens);
      summaryByModel[matchedModel].cost_usd += nodeCostUsd;
    }
  } catch (e) {
    // ข้าม Node ที่รันไม่ผ่านหรือไม่พบ
  }
}

// 4. สรุปเป็นเงินบาท (ใช้เรท 33 บาท/ดอลลาร์)
const grandTotalThb = grandTotalUsd * 33+1;

// จัดรูปแบบทศนิยมให้สวยงามสำหรับ Output
for (const model in summaryByModel) {
  const modelCostUsd = summaryByModel[model].cost_usd;
  summaryByModel[model].cost_thb = (modelCostUsd * 33).toFixed(4) + " บาท";
  summaryByModel[model].cost_usd = modelCostUsd.toFixed(6);
}

// 5. ส่งค่าออกไปแสดงผล
return {
  summary: {
    total_tokens_used: totalInputAll + totalOutputAll,
    tokens_breakdown: {
      input: totalInputAll,
      output_including_thoughts: totalOutputAll
    },
    cost_by_model: summaryByModel,
    grand_total: {
      usd: grandTotalUsd.toFixed(6),
      thb: grandTotalThb.toFixed(4) + " บาท"
    }
  }
};

// === Combine Machines: รวมชื่อเครื่องจาก Sheet 1 + Sheet 2 แล้วลบค่าซ้ำ ===

const sheet1 = $('Read Sheet 2').all();   // มีคอลัมน์ "เครื่อง"
const sheet2 = $('Read Sheet 1').all();   // มีคอลัมน์ "เครื่องจักร"

// ทำให้รูปแบบรหัสเครื่องเหมือนกัน เช่น PF8-8 -> PF8/8
// ถ้าไม่ต้องการให้แปลง ให้ลบ .replace(/-/g, '/') ออก
const normalize = (v) =>
  (v === undefined || v === null) ? '' : String(v).trim().replace(/-/g, '/');

const set = new Set();
for (const it of sheet1) { const c = normalize(it.json['เครื่อง']);     if (c) set.add(c); }
for (const it of sheet2) { const c = normalize(it.json['เครื่องจักร']); if (c) set.add(c); }

const machine = [...set];   // เช่น ["PF8/7", "PF8/8"]

return [{ json: { machine } }];

const incomingBinary = $('set-id').item.binary;
const machine = $('Combine Machines').first().json.machine || [];

const normalize = (v) =>
  (v === undefined || v === null) ? '' : String(v).trim().replace(/-/g, '/');

const machineSet = new Set(machine.map(normalize));
const sheet3 = $input.all();   // ทุกแถวจาก Read Sheet 3

const MACHINE_COL = 'Machine';
const NAME_COL    = 'Full_name';

const SEP = ' | ';

// ตัดให้เหลือ 4 ช่อง: ชื่อ | ประเภท | น้ำหนัก | สี   (ตัดช่องสุดท้าย เช่น ขึ้นเดี่ยว/ขึ้นคู่ ทิ้ง)
const toParts = (raw) => String(raw).split('|').map((p) => p.trim()).slice(0, 4);

// จับกลุ่มด้วย "ชื่อหน้า" = 3 ช่องแรก (ไม่รวมสี)
const chosen = new Map(); // front -> { trimmed, isSai }

for (const it of sheet3) {
  if (!machineSet.has(normalize(it.json[MACHINE_COL]))) continue;

  const raw = it.json[NAME_COL];
  if (raw === undefined || raw === null || String(raw).trim() === '') continue;

  const parts   = toParts(raw);
  const trimmed = parts.join(SEP);
  const front   = parts.slice(0, 3).join(SEP);
  const color   = parts[3] || '';
  const isSai   = color.endsWith('ใส');   // สีลงท้ายด้วย "ใส"

  if (!chosen.has(front)) {
    chosen.set(front, { trimmed, isSai });
